//! End-to-end `Watershed - Gradient` oracle comparison against a real
//! CellProfiler 4.2.8 run (fixtures/cppipe/secondary/, generated by
//! scripts/cppipe/generate_secondary_fixture.py from the pinned CellProfiler
//! source this repo installs via reference/install.sh -- never re-derived).

#[path = "support/npy.rs"]
mod npy;

use std::path::{Path, PathBuf};

use cp_anywhere::segmentation::secondary::{
    identify_secondary_objects, SecondaryMethod, SecondaryObjectsConfig,
};
use cp_anywhere::segmentation::{ThresholdMethod, ThresholdScope};

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/cppipe/secondary")
}

#[test]
fn watershed_gradient_matches_the_real_cellprofiler_oracle_run() {
    let dir = fixture_dir();
    let stain = npy::read(&dir.join("identify_secondary_objects_propagation.stain.npy"));
    assert_eq!(stain.descr, "<f8", "stain fixture should stay float64");
    let image: Vec<f64> = stain
        .data
        .chunks_exact(8)
        .map(|c| f64::from_le_bytes(c.try_into().unwrap()))
        .collect();
    // CellProfiler's own kept primary labels for this fixture; its
    // IdentifyPrimaryObjects run used exclude_size=False with interior
    // objects, so the kept array also supplies the unedited seed matrix.
    let labels = npy::read(&dir.join("identify_secondary_objects_propagation.nuclei_labels.npy"));
    assert_eq!(labels.descr, "<u4", "nuclei fixture should stay uint32");
    let seeds: Vec<u32> = labels
        .data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes(c.try_into().unwrap()))
        .collect();
    let (rows, cols) = (stain.shape[0], stain.shape[1]);

    // The fixture's IdentifySecondaryObjects settings, dumped by real
    // CellProfiler: Minimum Cross-Entropy on the stain, smoothing scale 0.0,
    // no correction factor or clamp, fill holes, no edge discard.
    let config = SecondaryObjectsConfig {
        method: SecondaryMethod::WatershedGradient,
        regularization_factor: 0.05,
        distance_to_dilate: 10.0,
        fill_holes: true,
        discard_edge: false,
        threshold_method: ThresholdMethod::Li,
        threshold_correction_factor: 1.0,
        threshold_range: (0.0, 1.0),
        threshold_smoothing_scale: 0.0,
        log_transform: false,
        threshold_scope: ThresholdScope::Global,
    };
    let result =
        identify_secondary_objects(&image, None, None, &seeds, &seeds, rows, cols, &config)
            .unwrap();

    let expected: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(
            dir.join("identify_secondary_objects_watershed_gradient.expected.json"),
        )
        .unwrap(),
    )
    .unwrap();
    let expected_labels: Vec<u32> = expected["cells_labels"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|row| {
            row.as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_i64().unwrap() as u32)
        })
        .collect();
    assert_eq!(result.labels, expected_labels);
}
